def T(text=None,kicker=None,hl=None,bg='dark',dur=45,lines=None,size=None):
    s={'type':'text','dur':dur,'bg':bg,'hl':hl or []}
    if text: s['text']=text
    if kicker: s['kicker']=kicker
    if lines: s['lines']=lines
    if size: s['size']=size
    return s
def CARD(img,tag=None,text=None,hl=None,bg='dark',dur=32):
    s={'type':'card','dur':dur,'image':img,'bg':bg,'hl':hl or []}
    if tag: s['tag']=tag
    if text: s['text']=text
    return s
def CTA(text,kw,dur=75,sub='لینک در بایو'): return {'type':'cta','dur':dur,'text':text,'sub':sub,'keyword':kw}
def LIST(items,title=None,mark='check',bg='dark',dur=70):
    s={'type':'list','dur':dur,'items':items,'mark':mark,'bg':bg}
    if title: s['title']=title
    return s
def STAT(v,label,suffix='',text=None,bg='dark',dur=55):
    s={'type':'stat','dur':dur,'value':v,'label':label,'suffix':suffix,'bg':bg}
    if text: s['text']=text
    return s
def SPLIT(b,a,text=None,hl=None,dur=84): return {'type':'split','dur':dur,'before':b,'after':a,'text':text,'hl':hl or []}
def QUOTE(t,by=None,bg='light',dur=60): return {'type':'quote','dur':dur,'text':t,'by':by,'bg':bg}
def SL(kind,title,hl=None,body=None,image=None,items=None,light=False,before=None,after=None):
    s={'kind':kind,'title':title,'titleHl':hl or [],'light':light}
    for k,v in [('body',body),('image',image),('items',items),('before',before),('after',after)]:
        if v: s[k]=v
    return s
def STORIES(cover_img,teaser,teaser_hl,poll,poll_hl,cta_title='اولین عکس محصولت مهمون وطن',n=3):
    s=[{'kind':'teaser','image':cover_img,'title':teaser,'titleHl':teaser_hl,'sub':'پست جدید رو ببین 👇','badge':'پست جدید'},
       {'kind':'poll','title':poll,'titleHl':poll_hl,'sub':'جوابت رو بزن؛ برای صنفت نمونه می‌فرستیم'},
       {'kind':'cta','image':IMG['jewelry'][1],'title':cta_title,'titleHl':['مهمون'],'sub':'با اعتبار هدیه‌ی ثبت‌نام، رایگان امتحان کن','badge':'هدیه'}]
    return s[:n]
def CAP(hook,lines,kw,cta='لینک توی بایوئه 👆'):
    out=hook+'\n\n'+'\n'.join(lines)+'\n\n🎁 با اعتبار هدیه‌ی ثبت‌نام، اولین عکس محصولت رو رایگان بساز.\n'+cta
    if kw: out+=f'\n\nکامنت بذار «{kw}» تا نمونه‌ی صنف خودت رو توی دایرکت برات بفرستیم.'
    return out
